arguments.content:
:root {
  --ink: #173a35;
  --ink-dark: #0d2b28;
  --paper: #f4f0e6;
  --paper-2: #eae4d7;
  --cream: #fffaf0;
  --coral: #f06449;
  --yellow: #f2c94c;
  --mint: #9dd6b9;
  --blue: #6bb5c6;
  --line: rgba(23, 58, 53, .22);
  --serif: Georgia, 'Times New Roman', serif;
  --sans: Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body { margin: 0; color: var(--ink); background: var(--paper); font-family: var(--sans); overflow-x: hidden; }
button, select, input { font: inherit; }
button, a { -webkit-tap-highlight-color: transparent; }
a { color: inherit; text-decoration: none; }
button { color: inherit; }
::selection { background: var(--yellow); color: var(--ink-dark); }
.skip-link { position: fixed; left: 1rem; top: -100px; z-index: 100; background: var(--yellow); padding: .8rem 1rem; font-weight: 800; }
.skip-link:focus { top: 1rem; }
.page-grain { position: fixed; inset: 0; opacity: .055; pointer-events: none; z-index: 99; background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.8'/%3E%3C/svg%3E"); }
.section-pad { padding-left: clamp(1.25rem, 6vw, 6.5rem); padding-right: clamp(1.25rem, 6vw, 6.5rem); }
.site-header { height: 88px; padding: 0 clamp(1.25rem, 4vw, 4rem); display: grid; grid-template-columns: 1fr auto 1fr; align-items: center; border-bottom: 1px solid var(--line); position: relative; z-index: 10; background: rgba(244, 240, 230, .92); backdrop-filter: blur(12px); }
.brand { display: flex; align-items: center; gap: .7rem; font-size: .7rem; line-height: .9; font-weight: 900; letter-spacing: .06em; width: max-content; }
.brand-mark { width: 32px; height: 32px; position: relative; display: inline-block; }
.brand-mark i { position: absolute; width: 19px; height: 19px; border-radius: 50%; background: var(--coral); border: 1.5px solid var(--ink); }
.brand-mark i:nth-child(1) { left: 0; top: 6px; }
.brand-mark i:nth-child(2) { right: 0; top: 0; background: var(--yellow); }
.brand-mark i:nth-child(3) { right: 1px; bottom: 0; background: var(--mint); }
.site-header nav { display: flex; gap: clamp(1.2rem, 3vw, 3rem); font-size: .8rem; font-weight: 700; }
.site-header nav a { position: relative; }
.site-header nav a::after { content: ''; position: absolute; left: 0; right: 100%; bottom: -6px; height: 2px; background: var(--coral); transition: right .25s; }
.site-header nav a:hover::after { right: 0; }
.site-header > .button { justify-self: end; }
.button { border: 0; display: inline-flex; align-items: center; justify-content: center; gap: 1.5rem; min-height: 56px; padding: 0 1.6rem; font-weight: 850; font-size: .87rem; cursor: pointer; transition: transform .2s, box-shadow .2s, background .2s; }
.button:hover { transform: translateY(-2px); box-shadow: 0 7px 0 rgba(13,43,40,.16); }
.button-small { min-height: 44px; padding: 0 1.1rem; font-size: .73rem; gap: 1rem; }
.button-ink { background: var(--ink); color: var(--cream); }
.button-primary { background: var(--coral); color: #fffaf0; border: 1px solid var(--ink); box-shadow: 4px 4px 0 var(--ink); }
.button-primary:hover { box-shadow: 6px 6px 0 var(--ink); }
.button-light { background: var(--cream); color: var(--ink); }
.full { width: 100%; }
.eyebrow { font-size: .68rem; letter-spacing: .15em; font-weight: 850; display: flex; align-items: center; gap: .7rem; margin: 0 0 1.4rem; }
.eyebrow > span { width: 26px; height: 2px; background: var(--coral); display: inline-block; }
.eyebrow-light { color: var(--cream); }
.hero { min-height: calc(100vh - 88px); display: grid; grid-template-columns: 1.03fr .97fr; align-items: center; gap: 3rem; padding-top: clamp(3.5rem, 7vw, 6.5rem); padding-bottom: clamp(4rem, 7vw, 7rem); overflow: hidden; }
.hero-copy { position: relative; z-index: 2; max-width: 780px; }
h1, h2 { font-family: var(--serif); font-weight: 400; letter-spacing: -.055em; margin: 0; }
h1 { font-size: clamp(4.6rem, 10vw, 9rem); line-height: .78; }
h1 em, h2 em { color: var(--coral); font-weight: 400; }
.hero-intro { max-width: 590px; font-family: var(--serif); font-size: clamp(1.15rem, 2vw, 1.55rem); line-height: 1.43; margin: 2.2rem 0 2rem; }
.hero-actions { display: flex; align-items: center; gap: 1.6rem; }
.text-button { border: 0; border-bottom: 1px solid currentColor; background: none; padding: .3rem 0; font-weight: 800; font-size: .84rem; cursor: pointer; }
.text-button span { margin-left: .6rem; }
.trust-row { display: flex; flex-wrap: wrap; gap: 1.4rem 2.2rem; border-top: 1px solid var(--line); margin-top: 3.5rem; padding-top: 1.1rem; font-size: .7rem; text-transform: uppercase; letter-spacing: .06em; }
.trust-row b { font-size: .78rem; margin-right: .25rem; }
.hero-visual { position: relative; aspect-ratio: 1; max-width: 690px; width: 100%; justify-self: center; display: grid; place-items: center; }
.hero-visual::before { content: ''; position: absolute; width: 67%; height: 67%; border-radius: 50%; background: var(--yellow); opacity: .16; filter: blur(2px); }
.orbit { position: absolute; border: 1px solid rgba(23,58,53,.38); border-radius: 50%; }
.orbit-one { width: 47%; height: 47%; }
.orbit-two { width: 69%; height: 69%; border-style: dashed; animation: spin 50s linear infinite; }
.orbit-three { width: 92%; height: 92%; opacity: .48; }
@keyframes spin { to { transform: rotate(360deg); } }
.sun { width: 36%; aspect-ratio: 1; border-radius: 50%; background: var(--coral); color: var(--cream); border: 2px solid var(--ink); position: relative; z-index: 2; display: flex; flex-direction: column; align-items: center; justify-content: center; text-align: center; font-size: clamp(.55rem, 1.1vw, .82rem); font-weight: 900; letter-spacing: .06em; line-height: 1.15; box-shadow: 9px 9px 0 var(--ink); }
.sun b { font-family: var(--serif); font-weight: 400; font-size: 2rem; line-height: 1; margin: .1rem 0; }
.orbit-label { position: absolute; z-index: 3; background: var(--cream); border: 1px solid var(--ink); border-radius: 99px; padding: .55rem .8rem; font-size: .61rem; font-weight: 900; letter-spacing: .04em; box-shadow: 3px 3px 0 var(--ink); }
.orbit-label span { color: var(--coral); margin-right: .35rem; }
.label-one { top: 10%; left: 13%; transform: rotate(-8deg); }
.label-two { right: -1%; top: 23%; transform: rotate(7deg); }
.label-three { bottom: 7%; right: 13%; transform: rotate(-4deg); }
.label-four { bottom: 16%; left: -2%; transform: rotate(5deg); }
.hero-squiggle { position: absolute; width: 35%; right: 10%; bottom: 6%; color: var(--coral); opacity: .75; }
.hero-stamp { position: absolute; right: 3%; bottom: 26%; width: 72px; height: 72px; border-radius: 50%; background: var(--mint); border: 1px solid var(--ink); display: grid; place-items: center; text-align: center; font-size: .58rem; font-weight: 900; line-height: 1.1; transform: rotate(10deg); }
.marquee { overflow: hidden; background: var(--ink); color: var(--cream); padding: 1rem 0; transform: rotate(-.6deg) scale(1.01); }
.marquee-track { display: flex; width: max-content; animation: marquee 28s linear infinite; align-items: center; gap: 1.6rem; font-size: .7rem; letter-spacing: .12em; font-weight: 850; }
.marquee-track i { color: var(--yellow); font-style: normal; font-size: 1rem; }
@keyframes marquee { to { transform: translateX(-50%); } }
.builder { padding-top: clamp(6rem, 10vw, 9rem); padding-bottom: clamp(6rem, 10vw, 9rem); }
.section-heading { margin-bottom: clamp(2.5rem, 5vw, 4.5rem); }
.split-heading { display: grid; grid-template-columns: 1.3fr .7fr; gap: 4rem; align-items: end; }
h2 { font-size: clamp(3rem, 6vw, 5.9rem); line-height: .92; }
.split-heading > p { max-width: 450px; margin: 0 0 .5rem; line-height: 1.65; font-size: .98rem; }
.builder-grid { display: grid; grid-template-columns: .88fr 1.12fr; gap: clamp(1.2rem, 3vw, 3rem); align-items: stretch; }
.controls-card { border: 1px solid var(--ink); background: var(--cream); box-shadow: 8px 8px 0 var(--ink); }
.control-block { padding: 1.6rem; border-bottom: 1px solid var(--line); }
.control-title { display: flex; align-items: center; gap: .85rem; margin-bottom: 1.2rem; }
.control-title > span { width: 27px; height: 27px; border-radius: 50%; border: 1px solid var(--ink); display: grid; place-items: center; font-size: .65rem; font-weight: 900; }
.control-title h3 { margin: 0; font-size: .86rem; }
.segmented { display: grid; grid-template-columns: repeat(3, 1fr); border: 1px solid var(--ink); }
.segmented button { border: 0; border-right: 1px solid var(--ink); background: transparent; min-height: 47px; font-size: .76rem; font-weight: 800; cursor: pointer; transition: .2s; }
.segmented button:last-child { border-right: 0; }
.segmented button.active { background: var(--ink); color: var(--cream); }
.style-options { display: grid; grid-template-columns: repeat(3, 1fr); gap: .65rem; }
.style-options button { border: 1px solid var(--line); background: transparent; padding: .8rem .5rem; cursor: pointer; display: flex; flex-direction: column; align-items: center; gap: .25rem; }
.style-options button.active { background: var(--yellow); border-color: var(--ink); box-shadow: 3px 3px 0 var(--ink); }
.style-icon { font-family: var(--serif); font-size: 1.6rem; line-height: 1; }
.style-options b { font-size: .73rem; }
.style-options small { font-size: .59rem; opacity: .75; }
.region-row { padding: 1.6rem; }
.region-row label { display: flex; align-items: center; gap: .45rem; font-size: .78rem; font-weight: 800; margin-bottom: .75rem; }
.region-row label i { font-size: .6rem; font-weight: 500; opacity: .6; }
.select-wrap { position: relative; }
.select-wrap select { appearance: none; width: 100%; border: 1px solid var(--ink); background: var(--paper); color: var(--ink); padding: .85rem 2.6rem .85rem .9rem; font-size: .78rem; font-weight: 700; outline-offset: 3px; cursor: pointer; }
.select-wrap > span { position: absolute; right: .9rem; top: 50%; transform: translateY(-50%); pointer-events: none; font-weight: 900; }
.recommendation { min-height: 660px; background: var(--mint); border: 1px solid var(--ink); position: relative; overflow: hidden; display: grid; grid-template-rows: auto 1fr auto; box-shadow: 8px 8px 0 var(--ink); }
.recommendation-top { padding: 1.2rem 1.3rem; display: flex; justify-content: space-between; align-items: center; position: relative; z-index: 2; }
.match-pill { border: 1px solid var(--ink); background: var(--cream); padding: .45rem .65rem; font-size: .58rem; font-weight: 900; letter-spacing: .06em; display: flex; align-items: center; gap: .4rem; }
.match-pill i { width: 6px; height: 6px; border-radius: 50%; background: var(--coral); }
.action-number { font-family: var(--serif); font-style: italic; font-size: .8rem; }
.action-illustration { position: absolute; inset: 0; pointer-events: none; overflow: hidden; }
.action-illustration .shape { position: absolute; border: 1.5px solid var(--ink); }
.action-illustration .plate { width: 330px; height: 330px; border-radius: 50%; right: -60px; top: 45px; background: var(--yellow); opacity: .92; }
.action-illustration .leaf { width: 110px; height: 48px; border-radius: 100% 0 100% 0; right: 85px; top: 120px; background: var(--ink); transform: rotate(-18deg); }
.action-illustration .leaf::after { content: ''; position: absolute; width: 1px; height: 90px; background: var(--mint); transform: rotate(47deg); left: 35px; top: -8px; }
.action-illustration .steam { width: 80px; height: 140px; border: 3px solid transparent; border-left-color: var(--ink); border-right-color: var(--ink); border-radius: 50%; top: 35px; right: 170px; transform: rotate(9deg); }
.action-content { position: relative; z-index: 2; align-self: end; background: rgba(255,250,240,.93); border-top: 1px solid var(--ink); padding: clamp(1.4rem, 3vw, 2.4rem); }
.action-kicker { font-size: .62rem; letter-spacing: .14em; font-weight: 900; margin: 0 0 .7rem; color: var(--coral); }
.action-content h3 { font-family: var(--serif); font-size: clamp(2.25rem, 4vw, 4rem); font-weight: 400; line-height: .98; letter-spacing: -.04em; margin: 0; max-width: 650px; }
.action-content > p:not(.action-kicker) { font-size: .9rem; line-height: 1.55; max-width: 620px; margin: 1rem 0 1.2rem; }
.action-meta { display: flex; gap: 0; border-block: 1px solid var(--line); margin-bottom: 1.25rem; }
.action-meta span { flex: 1; padding: .8rem .6rem; border-right: 1px solid var(--line); font-size: .64rem; text-transform: uppercase; letter-spacing: .05em; }
.action-meta span:last-child { border-right: 0; }
.action-meta b { display: block; font-size: .78rem; margin-bottom: .2rem; }
.another-button { display: block; margin: 1rem auto 0; border: 0; border-bottom: 1px solid; background: transparent; padding: .3rem; font-size: .74rem; font-weight: 800; cursor: pointer; }
.my-week { background: var(--ink); color: var(--cream); padding: clamp(5rem, 8vw, 8rem) 0; }
.week-inner { padding-top: 0; padding-bottom: 0; }
.week-header { display: flex; justify-content: space-between; align-items: end; border-bottom: 1px solid rgba(255,255,255,.25); padding-bottom: 2.5rem; }
.week-header h2 em { color: var(--yellow); }
.week-count { display: flex; align-items: center; gap: .7rem; }
.week-count > span { font-family: var(--serif); font-size: 4rem; line-height: 1; color: var(--yellow); }
.week-count small { font-size: .58rem; line-height: 1.3; letter-spacing: .08em; }
.week-empty { display: flex; align-items: center; gap: 1.2rem; min-height: 180px; opacity: .8; }
.empty-mark { width: 48px; height: 48px; border: 1px solid rgba(255,255,255,.4); border-radius: 50%; display: grid; place-items: center; color: var(--yellow); }
.week-empty h3 { font-family: var(--serif); font-size: 1.5rem; font-weight: 400; margin: 0 0 .3rem; }
.week-empty p { margin: 0; font-size: .8rem; }
.text-link-light { margin-left: auto; font-size: .75rem; text-decoration: underline; text-underline-offset: 4px; }
.plan-list { list-style: none; padding: 0; margin: 0; }
.plan-item { display: grid; grid-template-columns: 50px 1fr auto; gap: 1.2rem; align-items: center; border-bottom: 1px solid rgba(255,255,255,.2); padding: 1.35rem 0; }
.plan-number { width: 38px; height: 38px; border-radius: 50%; display: grid; place-items: center; background: var(--yellow); color: var(--ink); font-family: var(--serif); font-style: italic; }
.plan-item h3 { font-family: var(--serif); font-size: 1.4rem; font-weight: 400; margin: 0 0 .25rem; }
.plan-item p { font-size: .72rem; opacity: .72; margin: 0; }
.plan-item button { border: 1px solid rgba(255,255,255,.4); background: transparent; color: var(--cream); width: 36px; height: 36px; border-radius: 50%; cursor: pointer; }
.week-footer { display: flex; justify-content: space-between; align-items: center; padding-top: 2rem; }
.week-footer p { font-size: .85rem; opacity: .75; }
.ripples { padding-top: clamp(6rem, 10vw, 9rem); padding-bottom: clamp(6rem, 10vw, 9rem); }
.simulator-card { display: grid; grid-template-columns: .42fr .58fr; border: 1px solid var(--ink); box-shadow: 8px 8px 0 var(--ink); background: var(--cream); }
.simulator-controls { padding: clamp(1.5rem, 3vw, 2.6rem); border-right: 1px solid var(--ink); display: flex; flex-direction: column; justify-content: space-between; gap: 2.5rem; background: var(--paper-2); }
.sim-select-label { font-size: .6rem; letter-spacing: .12em; font-weight: 900; margin-bottom: .65rem; }
.large-select select { font-family: var(--serif); font-size: 1.2rem; font-weight: 400; background: var(--cream); padding-top: 1rem; padding-bottom: 1rem; }
.people-display > div:first-child { display: flex; align-items: baseline; gap: .7rem; margin-bottom: 1rem; }
.people-display span { font-family: var(--serif); font-size: 3.4rem; line-height: 1; }
.people-display small { font-size: .58rem; letter-spacing: .08em; font-weight: 800; }
input[type='range'] { appearance: none; width: 100%; height: 7px; background: linear-gradient(to right, var(--coral) 40%, rgba(23,58,53,.18) 40%); outline: none; }
input[type='range']::-webkit-slider-thumb { appearance: none; width: 24px; height: 24px; border-radius: 50%; background: var(--yellow); border: 2px solid var(--ink); cursor: grab; box-shadow: 2px 2px 0 var(--ink); }
input[type='range']::-moz-range-thumb { width: 21px; height: 21px; border-radius: 50%; background: var(--yellow); border: 2px solid var(--ink); cursor: grab; }
.range-labels { display: flex; justify-content: space-between; margin-top: .55rem; font-size: .56rem; font-weight: 800; }
.frequency-control > span { display: block; font-size: .6rem; letter-spacing: .12em; font-weight: 900; margin-bottom: .65rem; }
.segmented.small button { min-height: 39px; font-size: .67rem; }
.simulator-results { padding: clamp(1.5rem, 3vw, 2.6rem); }
.ripple-title { display: flex; justify-content: space-between; border-bottom: 1px solid var(--line); padding-bottom: 1rem; margin-bottom: 1.2rem; font-size: .6rem; letter-spacing: .1em; font-weight: 900; }
.ripple-title b { color: var(--coral); }
.impact-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: .8rem; }
.impact-card { min-height: 145px; padding: 1rem; border: 1px solid var(--line); position: relative; }
.impact-card .impact-icon { width: 32px; height: 32px; border: 1px solid var(--ink); border-radius: 50%; display: grid; place-items: center; font-family: var(--serif); font-size: 1.2rem; margin-bottom: .8rem; }
.impact-card strong { font-family: var(--serif); font-size: 2.25rem; font-weight: 400; line-height: 1; }
.impact-card small { font-size: .55rem; letter-spacing: .07em; font-weight: 850; display: block; margin-top: .35rem; }
.impact-card p { font-size: .68rem; opacity: .68; margin: .7rem 0 0; }
.impact-planet { background: #e2eee7; }
.impact-pocket { background: #f8e5d8; }
.impact-people { background: #e3e9ef; }
.impact-waste { background: #eee7f0; }
.scale-bar { margin-top: 1.4rem; }
.scale-labels { display: flex; justify-content: space-between; font-size: .54rem; font-weight: 900; letter-spacing: .08em; }
.scale-track { height: 11px; border: 1px solid var(--ink); margin: .55rem 0; position: relative; background: repeating-linear-gradient(90deg, transparent 0, transparent calc(10% - 1px), rgba(23,58,53,.24) calc(10% - 1px), rgba(23,58,53,.24) 10%); }
.scale-track > div { height: 100%; background: var(--coral); width: 40%; }
.scale-track i { position: absolute; left: 40%; top: -17px; transform: translateX(-50%); color: var(--ink); font-size: .65rem; }
.scale-bar p { font-size: .72rem; margin: .7rem 0 0; opacity: .75; }
.method-note { font-size: .63rem; opacity: .65; max-width: 780px; margin: 1.2rem 0 0; }
.principles { background: var(--yellow); border-top: 1px solid var(--ink); border-bottom: 1px solid var(--ink); padding-top: clamp(5rem, 9vw, 8rem); padding-bottom: clamp(5rem, 9vw, 8rem); }
.principle-heading { margin-bottom: 4rem; }
.principle-heading h2 em { color: var(--ink); }
.principle-grid { display: grid; grid-template-columns: repeat(3, 1fr); border: 1px solid var(--ink); }
.principle-grid article { padding: clamp(1.4rem, 3vw, 2.5rem); border-right: 1px solid var(--ink); position: relative; min-height: 300px; }
.principle-grid article:last-child { border-right: 0; }
.principle-num { font-size: .6rem; font-weight: 900; }
.principle-icon { width: 80px; height: 80px; border-radius: 50%; border: 1px solid var(--ink); display: grid; place-items: center; font-family: var(--serif); font-size: 3rem; margin: 2.5rem 0 1.6rem; background: var(--cream); }
.principle-grid h3 { font-family: var(--serif); font-size: 1.65rem; font-weight: 400; margin: 0 0 .6rem; }
.principle-grid p { font-size: .8rem; line-height: 1.6; margin: 0; max-width: 330px; }
.method { background: var(--ink); color: var(--cream); }
.method-card { display: grid; grid-template-columns: 1fr 1fr; gap: clamp(3rem, 8vw, 9rem); }
.method-title h2 em { color: var(--yellow); }
.method-copy { padding-top: .4rem; }
.method-copy > p { font-family: var(--serif); font-size: 1.35rem; line-height: 1.5; margin: 0 0 2rem; }
details { border-block: 1px solid rgba(255,255,255,.25); margin-bottom: 2rem; }
summary { list-style: none; display: flex; justify-content: space-between; padding: 1rem 0; font-size: .76rem; font-weight: 850; cursor: pointer; }
summary::-webkit-details-marker { display: none; }
details[open] summary span { transform: rotate(45deg); }
details ul { padding-left: 1.2rem; font-size: .75rem; line-height: 1.7; opacity: .8; padding-bottom: 1rem; }
.light-text { color: var(--cream); }
.site-footer { background: var(--coral); color: var(--ink); padding-top: clamp(4rem, 8vw, 7rem); padding-bottom: 1.5rem; }
.footer-top { display: flex; justify-content: space-between; align-items: end; padding-bottom: 4rem; }
.footer-word { font-size: clamp(3rem, 8vw, 7rem); line-height: .78; letter-spacing: -.05em; font-weight: 900; margin: 0 0 2rem !important; }
.footer-top p { font-family: var(--serif); font-size: 1rem; line-height: 1.5; }
.round-cta { width: 170px; height: 170px; border-radius: 50%; border: 2px solid var(--ink); display: flex; align-items: center; justify-content: center; gap: .7rem; background: var(--yellow); box-shadow: 7px 7px 0 var(--ink); transition: transform .25s; }
.round-cta:hover { transform: rotate(5deg) translateY(-3px); }
.round-cta span { font-size: .75rem; line-height: 1.1; font-weight: 900; }
.round-cta b { font-size: 1.5rem; }
.footer-bottom { border-top: 1px solid var(--ink); padding-top: 1.2rem; display: flex; justify-content: space-between; font-size: .64rem; font-weight: 750; }
.toast { position: fixed; left: 50%; bottom: 1.5rem; transform: translate(-50%, 150%); z-index: 50; background: var(--ink); color: var(--cream); border: 1px solid var(--cream); padding: .85rem 1.2rem; font-size: .76rem; font-weight: 750; box-shadow: 5px 5px 0 var(--coral); transition: transform .3s; max-width: 90vw; text-align: center; }
.toast.show { transform: translate(-50%, 0); }

@media (max-width: 950px) {
  .site-header { grid-template-columns: 1fr auto; }
  .site-header nav { display: none; }
  .hero { grid-template-columns: 1fr; padding-top: 4rem; }
  .hero-copy { max-width: 760px; }
  .hero-visual { margin-top: 1rem; }
  .split-heading { grid-template-columns: 1fr; gap: 1.5rem; }
  .builder-grid { grid-template-columns: 1fr; }
  .recommendation { min-height: 680px; }
  .simulator-card { grid-template-columns: 1fr; }
  .simulator-controls { border-right: 0; border-bottom: 1px solid var(--ink); display: grid; grid-template-columns: 1fr 1fr; }
  .people-display { grid-column: 1 / -1; }
  .frequency-control { grid-column: 1 / -1; }
  .method-card { grid-template-columns: 1fr; gap: 3rem; }
}

@media (max-width: 650px) {
  .site-header { height: 72px; }
  .site-header > .button { display: none; }
  .site-header { grid-template-columns: 1fr; }
  h1 { font-size: clamp(4rem, 20vw, 6rem); }
  .hero { min-height: auto; }
  .hero-actions { align-items: flex-start; flex-direction: column; }
  .trust-row { gap: .8rem 1.2rem; }
  .hero-visual { width: 115%; margin-left: -7%; }
  .orbit-label { font-size: .5rem; }
  .label-one { left: 5%; }
  .label-two { right: -5%; }
  .label-three { right: 4%; }
  .hero-stamp { display: none; }
  .control-block, .region-row { padding: 1.1rem; }
  .style-options { gap: .4rem; }
  .style-options button { padding-inline: .2rem; }
  .style-options small { display: none; }
  .action-content h3 { font-size: 2.4rem; }
  .action-meta { flex-wrap: wrap; }
  .action-meta span { min-width: 33%; }
  .week-header { align-items: start; }
  .week-count { flex-direction: column; align-items: end; gap: 0; }
  .week-count > span { font-size: 2.8rem; }
  .week-empty { flex-wrap: wrap; }
  .text-link-light { margin-left: 0; }
  .plan-item { grid-template-columns: 40px 1fr auto; gap: .7rem; }
  .plan-item p { display: none; }
  .simulator-controls { display: flex; }
  .impact-grid { grid-template-columns: 1fr 1fr; }
  .impact-card { min-height: 130px; padding: .8rem; }
  .impact-card strong { font-size: 1.8rem; }
  .principle-grid { grid-template-columns: 1fr; }
  .principle-grid article { border-right: 0; border-bottom: 1px solid var(--ink); }
  .principle-grid article:last-child { border-bottom: 0; }
  .principle-icon { margin: 1.5rem 0 1rem; }
  .footer-top { flex-direction: column; align-items: flex-start; gap: 3rem; }
  .round-cta { width: 135px; height: 135px; align-self: center; }
  .footer-bottom { flex-direction: column; gap: .8rem; }
}

